import {seedState,makeOutline,generateBook,regenerateText,sceneSVG,characterSVG,safeTopic} from './engine.js';
import {printBook,exportLibrary,validateImport,restoreLibraryImages} from './output.js';
import {migrateWorldState,getActiveWorld,getCharacterSheet,markCharacterSheetConfirmed} from './image-generation/world.js';
import {getStylePreset} from './image-generation/styles.js';
import {hydrateImageAssets,getImageURL} from './image-generation/assets.js';
import {configureImageUI,renderImageSettings,renderGenerationControls,renderCharacterImageControls} from './image-generation/settings-ui.js';

const KEY='donghwa-workshop-v1';
const defaults={style:'수채화 그림책풍',defaultLanguage:'dual',defaultPages:12,defaultLayout:'booklet',dailyLimit:3,rate:0.85};
let state;
try{const saved=localStorage.getItem(KEY);state=saved?validateImport(saved,{allowStoredAssets:true}):seedState()}catch{state=seedState()}
state.settings={...defaults,...state.settings};state.daily=state.daily||{};state.backgrounds=state.backgrounds||[];
state.settings.style=({watercolor:'수채화 그림책풍',crayon:'파스텔 크레용',flat:'플랫 일러스트',cartoon:'만화풍'})[state.settings.style]||state.settings.style;
state.backgrounds=state.backgrounds.map(b=>({...b,type:b.type||({home:'home',forest:'forest',moon:'space',garden:'forest',beach:'sea'})[b.id]||'forest'}));
migrateWorldState(state);state.settings.style=getStylePreset(getActiveWorld(state).stylePresetId).name;
let view='library',childMode=false,parentUnlocked=false,tab='all',sort='recent',query='',activeBook=null;
let wizard=null,draft=null,editPage=0,reader=null,studio=null,pinCallback=null,modalFocus=null;
const root=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
const paths={book:'M3 5q5-2 9 1q4-3 9-1v15q-5-2-9 1q-4-3-9-1z M12 6v15',spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z M21 2v4 M19 4h4',home:'m3 11 9-8 9 8 M5 10v11h14V10 M9 21v-8h6v8',heart:'M20.8 4.6a5.4 5.4 0 0 0-7.6 0L12 5.8l-1.2-1.2a5.4 5.4 0 0 0-7.6 7.6L12 21l8.8-8.8a5.4 5.4 0 0 0 0-7.6z',characters:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.8 M13 7a4 4 0 1 1-8 0a4 4 0 0 1 8 0',plus:'M12 5v14 M5 12h14',settings:'M12 8a4 4 0 1 1 0 8a4 4 0 0 1 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',child:'M15 5a3 3 0 1 1-6 0a3 3 0 0 1 6 0 M5 10l7 3 7-3 M12 13v5 M8 22l4-4 4 4',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',back:'m14 5-7 7 7 7',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',search:'M16 10a6 6 0 1 1-12 0a6 6 0 0 1 12 0 m-2 4 6 6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',print:'M6 9V3h12v6 M6 17H3V9h18v8h-3 M6 14h12v7H6z M17 12h1',leaf:'M20 3C9 2 2 8 5 17s17 1 15-14 M5 20l11-12',check:'m5 12 4 4 10-10',close:'m6 6 12 12 M18 6 6 18',play:'m8 4 13 8-13 8z',pause:'M8 4v16 M16 4v16',headphones:'M3 14v-3a9 9 0 0 1 18 0v3 M3 13h4v8H3z M17 13h4v8h-4z',volume:'M3 9h4l5-4v14l-5-4H3z M16 8q5 4 0 8 M19 5q7 7 0 14',refresh:'M20 8a8 8 0 1 0 0 8 M20 3v5h-5',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V3 m-5 5 5-5 5 5 M4 16v5h16v-5',globe:'M21 12a9 9 0 1 1-18 0a9 9 0 0 1 18 0 M3 12h18 M12 3q-8 9 0 18q8-9 0-18',clock:'M21 12a9 9 0 1 1-18 0a9 9 0 0 1 18 0 M12 7v5l3 2',edit:'m15 4 5 5-11 11-5 1 1-5z M13 6l5 5',trash:'M3 6h18 M6 6l1 15h10l1-15 M9 6V3h6v3',info:'M21 12a9 9 0 1 1-18 0a9 9 0 0 1 18 0 M12 11v6 M12 7v1',folder:'M3 5h7l2 3h9v13H3z'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,kind='outline',ic='',data='')=>`<button type="button" class="btn btn-${kind}" data-action="${action}" ${data}>${ic?icon(ic):''}${label}</button>`;
const date=v=>new Date(v).toLocaleDateString('ko-KR',{month:'2-digit',day:'2-digit'}).replace(/\.\s*$/,'');
const localDay=()=>new Date().toLocaleDateString('en-CA');
const char=id=>state.characters.find(c=>c.id===id)||state.characters[0];
const bookById=id=>state.books.find(b=>b.id===id);
const languageLabel=l=>({dual:'한·영',bilingual:'한영',ko:'한글',en:'영어'}[l]||'한·영');
const appearance=c=>({...c,color:c.color||'#efc954'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('저장 공간이 부족해요. 백업 후 공간을 확보해 주세요.');return false}}
let toastTimer;function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3800)}
function illustration(book,i=0){const p=book.pages[Math.min(i,book.pages.length-1)];const url=p.imageAssetId?getImageURL(p.imageAssetId):(p.imageUrl&&!p.imageUrl.startsWith('asset:')?p.imageUrl:null);if(p.imageAssetId&&!url)return '<div class="image-missing">저장된 그림을 불러올 수 없어요.<br>백업에서 그림을 복원해 주세요.</div>';if(url)return `<img class="generated-illustration" src="${esc(url)}" alt="${esc(book.title)} · ${i+1}쪽 생성 그림">`;const cast=(book.characterIds||[]).map(id=>appearance(char(id)));return sceneSVG(p.scene,cast.length?cast:[state.characters[0]],p.artVariant||0)}
function cover(book){const theme=book.theme||book.pages[0]?.scene?.theme||'default';return `<div class="book-cover cover-${esc(theme)}"><div class="cover-art">${illustration(book,Math.min(2,book.pages.length-1))}</div><div class="cover-kicker">우리 아이의 작은 모험 · ${esc(book.episode||1)}번째 이야기</div><div class="cover-title">${esc(book.title)}<span class="cover-subtitle">${esc(book.titleEn||'A little story, a big adventure')}</span></div><div class="cover-footer">DONGHWA WORKSHOP</div></div>`}
function bookCard(book){return `<article class="book-card">${!childMode?`<button class="book-favorite ${book.favorite?'is-favorite':''}" data-action="favorite" data-id="${esc(book.id)}" aria-label="${book.favorite?'즐겨찾기 해제':'즐겨찾기 추가'}">${icon('heart')}</button>`:''}<button class="book-cover-button" data-action="open-book" data-id="${esc(book.id)}" aria-label="${esc(book.title)} 열기" style="display:block;width:100%;padding:0">${cover(book)}</button><div class="book-info"><button class="book-name" data-action="open-book" data-id="${esc(book.id)}">${esc(book.title)}</button><p class="book-series">${esc(book.series)} · ${book.episode||1}편</p><div class="book-meta"><span class="lang-tag">${languageLabel(book.language)}</span><span>${book.pages.length}쪽</span><span>·</span><span>${date(book.createdAt)}</span><span class="print-badge">${icon(book.printedAt?'check':'print')}${book.printedAt?'인쇄 기록':'인쇄 전'}</span></div></div></article>`}
function protectedAction(fn){if(parentUnlocked&&!childMode)return fn();pinCallback=()=>{childMode=false;parentUnlocked=true;fn()};openPin()}
async function hashPin(pin){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(pin));return [...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function showModal(content,cls=''){modalFocus=document.activeElement;modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${cls.includes('pin')?'부모 PIN':'대화상자'}">${content}</section></div>`;requestAnimationFrame(()=>modalRoot.querySelector('input,button,select')?.focus())}
function closeModal(){if(reader){stopSpeech();reader=null}modalRoot.innerHTML='';modalFocus?.focus();pinCallback=null}
function modalHeader(title){return `<div class="modal-header"><h3>${title}</h3><button class="close-btn" data-action="close-modal" aria-label="닫기">${icon('close')}</button></div>`}
function openPin(){const setup=!state.settings.pinHash;showModal(`${icon('lock')}<h3>${setup?'우리 가족의 부모 PIN':'부모 모드로 들어가기'}</h3><p class="modal-intro">${setup?'만들기와 설정을 보호할 숫자 4자리를 정해 주세요.<br>이 브라우저에 저장되며, 아이에게는 읽기만 열립니다.':'숫자 4자리를 입력하면 만들기와 설정이 열립니다.'}</p><form id="pin-form"><input class="pin-input" id="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" minlength="4" required autocomplete="off" aria-label="부모 PIN 4자리">${setup?'<div><input class="pin-input" id="pin-confirm" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" minlength="4" required autocomplete="off" aria-label="부모 PIN 확인" placeholder="····"></div><small class="small-label">같은 PIN을 한 번 더 입력해 주세요.</small>':''}<p class="pin-error" id="pin-error"></p><button class="btn btn-green" type="submit">${setup?'PIN 설정하고 시작':'부모 모드 열기'}${icon('arrow')}</button></form><button class="btn btn-plain btn-small" data-action="close-modal">취소</button>`,'pin-modal')}
function render(){
 const nav=(id,label,ic)=>`<button class="nav ${view===id?'active':''} ${id==='create'?'create-nav':''}" data-action="nav" data-view="${id}">${icon(ic)}<span>${label}</span>${!parentUnlocked&&id!=='library'?icon('lock','lock'):''}</button>`;
 root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><svg class="brand-mark" viewBox="0 0 40 44" aria-hidden="true"><path d="M4 16q9-4 16 1q7-5 16-1v23q-9-4-16 1q-7-5-16-1z" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M20 18v22 M20 9q5-7 13-5q-2 10-13 9 M20 14l8-7" fill="none" stroke="currentColor" stroke-width="1.5"/></svg><div><h1>동화공방</h1><small>DONGHWA WORKSHOP</small></div></div><div class="family"><div class="family-avatar">${state.characters[0]?characterSVG(state.characters[0]):''}</div><div><strong>${esc(state.characters[0]?.name||'우리 아이')}네 이야기 공방</strong><small>작은 이야기가 자라는 곳</small></div></div><nav><div class="nav-group">우리 가족의 공간</div>${nav('library','우리 책장','book')}${!childMode?nav('materials','이야기 재료','characters')+nav('create','이야기 만들기','spark'):''}${childMode?`<button class="nav ${tab==='favorites'?'active':''}" data-action="child-favorites">${icon('heart')}<span>좋아하는 책</span></button>`:''}${!childMode?`<div class="nav-group" style="margin-top:29px">공방 관리</div>${nav('settings','부모 설정','settings')}`:''}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf')}화면보다 종이로,<br>우리 아이의 속도로 읽어요.</div><div class="sidebar-footer"><span>작은 이야기, 큰 상상</span><span>v0.1</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${icon('home')}<span>우리 가족의 공간</span>${icon('chevron')}<span>${({library:'우리 책장',materials:'이야기 재료',create:'이야기 만들기',settings:'부모 설정',detail:'책 이야기',edit:'이야기 다듬기'})[view]||'우리 책장'}</span></div><div class="mobile-brand">${icon('book')}동화공방</div><div class="top-actions"><span class="local-label">${icon('check')}이 기기에 저장</span><button class="mode-btn" data-action="toggle-mode">${icon(childMode?'lock':'child')}${childMode?'부모 모드':'아이 모드'}</button><div class="top-avatar">부모</div></div></header><div id="page-content">${pageContent()}</div><footer class="page-footer"><span>${icon('leaf')}우리 가족만의 이야기가, 아이의 세상을 넓혀요.</span><span>글은 로컬 샘플 · 그림은 World 엔진 선택 · 이 브라우저에 보관됩니다.</span></footer></main></div>`;
}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div>`}
function pageContent(){if(view==='materials')return materialsPage();if(view==='create')return createPage();if(view==='settings')return settingsPage();if(view==='detail')return detailPage();if(view==='edit')return editorPage();return libraryPage()}
function filteredBooks(){let b=state.books.filter(x=>x.approved!==false);if(tab==='favorites')b=b.filter(x=>x.favorite);if(tab==='unprinted')b=b.filter(x=>!x.printedAt);if(query){const q=query.toLocaleLowerCase();b=b.filter(x=>[x.title,x.titleEn,x.series,x.topic,x.theme,...(x.characterIds||[]).map(id=>char(id)?.name)].join(' ').toLocaleLowerCase().includes(q))}return b.sort((a,b)=>sort==='popular'?(b.reads||0)-(a.reads||0):new Date(b.createdAt)-new Date(a.createdAt))}
function libraryPage(){const books=filteredBooks();let cards=books.map(bookCard).join('');if(tab==='series'){const groups=Map.groupBy(books,b=>b.series);cards=[...groups].map(([series,list])=>`<section class="series-group"><h3>${esc(series)} <span class="count">${list.length}권</span></h3><div class="books-grid">${list.sort((a,b)=>a.episode-b.episode).map(bookCard).join('')}</div></section>`).join('')}
 return `${heading(childMode?'우리 아이의 책장':'우리 책장',childMode?'좋아하는 책을 골라, 함께 듣고 읽어요.':'한 권 한 권, 우리 아이의 이야기가 쌓이는 곳.',`<div class="date-pill">${icon('calendar')}${new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'})}</div>`)}${!childMode?`<section class="hero"><div class="hero-content"><div class="eyebrow">${icon('spark')}A LITTLE STORY, A BIG ADVENTURE</div><h3>아이의 오늘이,<br>한 권의 동화로.</h3><p>익숙한 얼굴, 좋아하는 세상.<br>우리 아이가 주인공인 이야기를 만들어 보세요.</p>${btn('새 이야기 만들기','new-story','primary','plus')}</div></section><div class="materials-strip"><span class="strip-label">${icon('characters')}우리 집 이야기 친구들</span><div class="strip-divider"></div><div class="strip-characters">${state.characters.slice(0,4).map(c=>`<span class="mini-char"><span class="mini-portrait">${characterSVG(c)}</span>${esc(c.name)}</span>`).join('')}</div><button class="strip-link" data-action="nav" data-view="materials">재료 둘러보기${icon('arrow')}</button></div>`:''}<section><div class="shelf-header"><div class="shelf-title">${childMode?'읽고 싶은 이야기':'나의 작은 책장'}<span class="count">${books.length}권의 이야기</span></div><div class="shelf-options"><select id="sort" aria-label="책 정렬"><option value="recent" ${sort==='recent'?'selected':''}>최근 만든 순</option><option value="popular" ${sort==='popular'?'selected':''}>많이 읽은 순</option></select><span class="view-icon">${icon('grid')}</span></div></div><div class="shelf-toolbar"><div class="tabs">${[['all','전체','book'],['favorites','즐겨찾기','heart'],['series','시리즈','folder'],...(!childMode?[['unprinted','인쇄 전','print']]:[])].map(([id,label,ic])=>`<button class="tab ${tab===id?'active':''}" data-action="tab" data-tab="${id}">${icon(ic)}${label}${id==='all'?`<small>${state.books.filter(b=>b.approved!==false).length}</small>`:''}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search-books" placeholder="제목, 주제, 등장인물 검색" value="${esc(query)}" aria-label="책 검색"></label></div><div class="books-grid" id="books-grid">${cards||`<div class="empty">${icon('book')}<h3>${query?'찾는 이야기가 아직 없어요':'이곳에 이야기를 쌓아 볼까요?'}</h3><p>${query?'다른 검색어로 찾아보세요.':'한 번 만든 이야기는 언제든 다시 꺼내 읽을 수 있어요.'}</p>${!childMode?btn('새 이야기 만들기','new-story','soft','plus'):''}</div>`}</div></section>`}
function materialsPage(){return `${heading('이야기 재료','한 번 만든 친구와 장소를, 다음 이야기에도 그대로.',btn('등장인물 만들기','new-character','primary','plus'))}<div class="style-banner"><div><strong>${icon('leaf')} 우리 집 세계 · ${esc(state.settings.style)}</strong><small>얼굴과 색상은 캐릭터 시트에 고정되어 모든 이야기에 함께해요.</small></div>${btn('그림체 설정','nav','outline','settings','data-view="settings"')}</div><div class="section-header"><h3>등장인물 서랍 <span class="count">${state.characters.length}명</span></h3><span class="small-label">기본 모습 · 같은 얼굴로 만나요</span></div><div class="character-grid">${state.characters.map(c=>`<article class="character-card"><div class="character-picture">${characterSVG(c,c.variant||0)}</div><span class="role-tag">${esc(c.role)}</span><h4>${esc(c.name)} <span class="count">${esc(c.nameEn)}</span></h4><p>${state.books.filter(b=>b.characterIds?.includes(c.id)).length}권에 등장 · ${esc(c.description||'우리 집 이야기 친구')}</p>${btn('캐릭터 시트 보기','character-sheet','outline','characters',`data-id="${esc(c.id)}"`)}${renderCharacterImageControls(c,state)}</article>`).join('')}</div><div class="section-header"><h3>배경 서랍 <span class="count">${state.backgrounds.length}곳</span></h3>${btn('장소 추가','new-background','outline','plus')}</div><div class="background-grid">${state.backgrounds.map(b=>`<article class="background-card"><div class="background-emoji">${({home:'🏡',school:'🏫',forest:'🌳',space:'🌙',sea:'🐚'})[b.type]||'🌿'}</div><h4>${esc(b.name)}</h4><p>${esc(b.description||b.features||'이야기가 시작되는 작은 장소')}</p></article>`).join('')}</div>`}
function startStory(previous=null){wizard={step:1,characterIds:previous?[...previous.characterIds]:[state.characters[0]?.id].filter(Boolean),backgroundIds:previous?.backgroundIds||[],topic:'',language:previous?.language||state.settings.defaultLanguage,pageCount:previous?.pageCount||state.settings.defaultPages,englishLevel:previous?.englishLevel||'repeat',value:'none',ending:'home',series:previous?.series||'',previousBookId:previous?.id||null,outline:null};view='create';render();window.scrollTo(0,0)}
function createPage(){if(!wizard){wizard={step:1,characterIds:[state.characters[0]?.id].filter(Boolean),backgroundIds:[],topic:'',language:state.settings.defaultLanguage,pageCount:state.settings.defaultPages,englishLevel:'repeat',value:'none',ending:'home',series:'',previousBookId:null,outline:null}}
 const w=wizard;const steps=['재료 고르기','이야기 설정','줄거리 확인'];let inner='';
 if(w.step===1)inner=`<h3>누구와 함께 떠날까요?</h3><p class="section-sub">첫 번째로 고른 친구가 주인공이에요. 조연은 최대 4명까지 함께할 수 있어요.</p><div class="selection-grid">${state.characters.map(c=>`<button class="selection ${w.characterIds.includes(c.id)?'selected':''}" data-action="select-character" data-id="${esc(c.id)}">${characterSVG(c,c.variant||0)}<strong>${esc(c.name)}</strong><small>${w.characterIds[0]===c.id?'이번 이야기의 주인공':esc(c.role)}</small></button>`).join('')}</div><label class="form-label">이야기가 펼쳐질 장소 <span class="count">최대 3곳 · 선택하지 않으면 자동</span></label><div class="chips">${state.backgrounds.map(b=>`<button class="chip ${w.backgroundIds.includes(b.id)?'selected':''}" data-action="select-background" data-id="${esc(b.id)}">${esc(b.name)}</button>`).join('')}</div>${w.previousBookId?`<div class="notice" style="margin-top:24px">지난 이야기에서 이어집니다.<br>${esc(bookById(w.previousBookId)?.summary||bookById(w.previousBookId)?.title)}</div>`:''}`;
 if(w.step===2)inner=`<h3>오늘은 어떤 이야기를 만들까요?</h3><p class="section-sub">아이가 좋아하는 것, 오늘 있었던 일을 들려주세요.</p><div class="field"><label for="topic">이야기 주제</label><textarea id="topic" maxlength="400" placeholder="예: 유하가 공룡 친구와 함께 길을 잃은 별을 찾아주는 이야기">${esc(w.topic)}</textarea></div><div class="chips">${['공룡 친구와 소풍','달에 놀러 간 날','비 오는 날의 모험','바닷속 보물 찾기','처음 유치원에 간 날','친구의 생일 파티'].map(t=>`<button class="chip" data-action="topic-chip" data-topic="${t}">${t}</button>`).join('')}<button class="chip" data-action="child-pick">${icon('child')}아이가 고르기</button></div><div class="form-grid" style="margin-top:26px">${selectField('language','언어',[['dual','한글판 · 영어판 두 권'],['bilingual','한 쪽에 한글 + 영어'],['ko','한글만'],['en','영어만']],w.language)}${selectField('pageCount','이야기 길이',[[8,'8쪽 · 짧은 이야기'],[12,'12쪽 · 기본'],[16,'16쪽'],[24,'24쪽']],w.pageCount)}${selectField('englishLevel','영어 수준',[['repeat','반복 문장 · 한 쪽 한 문장'],['short','짧은 문장 · 한두 문장'],['chapter','챕터 수준 · 긴 문장']],w.englishLevel)}${selectField('value','함께 생각할 가치',[['none','없음 · 즐거운 이야기'],['sharing','나눔'],['courage','용기'],['kindness','친절'],['brushing','양치하기']],w.value)}${selectField('ending','이야기의 끝',[['home','집에 돌아와 잠들어요'],['open','다음 모험을 기다려요']],w.ending)}<div class="field"><label for="series">시리즈 이름 <span class="count">비워두면 새 시리즈</span></label><input id="series" maxlength="60" value="${esc(w.series)}" placeholder="예: 유하의 작은 모험" ${w.previousBookId?'readonly':''}></div></div><div class="notice" style="margin-top:22px">로컬 샘플 생성: 주제에 맞는 이야기 틀과 캐릭터 그림을 사용해요. 자유로운 AI 글·그림 생성은 아직 연결되지 않았어요.</div>`;
 if(w.step===3)inner=`<h3>이야기의 길을 먼저 살펴봐요</h3><p class="section-sub">각 쪽의 줄거리를 직접 고칠 수 있어요. 본문을 만든 뒤에도 한 쪽씩 수정할 수 있습니다.</p><div class="outline-list">${(w.outline||[]).map((p,i)=>`<div class="outline-row"><span class="outline-number">${i+1}</span><textarea data-outline="${i}" aria-label="${i+1}쪽 줄거리">${esc(p.ko)}</textarea></div>`).join('')}</div><div class="notice" style="margin-top:20px">시작은 작은 호기심으로, 끝은 포근하게. 부모가 확정하기 전에는 아이 책장에 나타나지 않아요.</div>`;
 return `${heading(w.previousBookId?'다음 이야기 이어 만들기':'이야기 만들기','익숙한 친구들과, 세상에 하나뿐인 새 이야기.')}<div class="wizard"><div class="steps">${steps.map((s,i)=>`<div class="step ${i+1===w.step?'active':i+1<w.step?'done':''}"><b>${i+1<w.step?'✓':i+1}</b>${s}</div>`).join('')}</div><section class="panel">${inner}</section><div class="wizard-actions">${btn(w.step===1?'책장으로':'이전 단계',w.step===1?'library':'wizard-back','outline','back')}<span class="wizard-hint">${icon('lock')}부모가 확인하고 아이에게 전해요.</span>${btn(w.step===3?'본문 만들고 다듬기':'다음 단계',w.step===3?'generate':'wizard-next','green','arrow')}</div></div>`}
function selectField(id,label,options,value){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${options.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('')}</select></div>`}
function syncWizard(){if(wizard?.step===2){for(const k of ['topic','language','pageCount','englishLevel','value','ending','series'])wizard[k]=document.getElementById(k)?.value??wizard[k];wizard.pageCount=Number(wizard.pageCount)}if(wizard?.step===3)document.querySelectorAll('[data-outline]').forEach(e=>wizard.outline[Number(e.dataset.outline)].ko=e.value)}
function editorPage(){if(!draft){view='library';return libraryPage()}const p=draft.pages[editPage];return `${heading('이야기 다듬기','한 쪽씩 살펴보고, 우리 아이에게 어울리는 말로 바꿔 주세요.',`<span class="small-label">부모 미확정 · 초안</span>`)}${renderGenerationControls(draft)}<div class="editor-title"><input id="book-title" maxlength="80" aria-label="책 제목" value="${esc(draft.title)}"></div><div class="editor-layout"><div class="page-rail">${draft.pages.map((p,i)=>`<button class="page-thumb ${i===editPage?'active':''}" data-action="edit-page" data-page="${i}" aria-label="${i+1}쪽 편집">${illustration(draft,i)}<span>${i+1}쪽</span></button>`).join('')}</div><section class="panel"><div class="editor-main"><div class="editor-art">${illustration(draft,editPage)}<div class="editor-tools">${btn('샘플 그림 변형','regenerate-art','outline','refresh')}</div></div><div class="editor-text"><div class="field"><label for="page-ko">${editPage+1}쪽 · 한글</label><textarea id="page-ko">${esc(p.ko)}</textarea></div><div class="field"><label for="page-en">English · ${editPage+1}</label><textarea id="page-en">${esc(p.en)}</textarea></div>${btn('샘플 문장 다시 쓰기','regenerate-text','outline','refresh')}<span class="small-label">그림은 고정 캐릭터 기반 SVG 장면입니다.</span></div></div><div class="editor-bottom"><span>${icon('check')}확정하면 읽기와 인쇄가 함께 열려요.</span>${btn('확정하고 책장에 저장','approve-book','primary','check')}</div></section></div>`}
function syncDraft(){if(draft){draft.title=document.getElementById('book-title')?.value.trim()||draft.title;const p=draft.pages[editPage];p.ko=document.getElementById('page-ko')?.value??p.ko;p.en=document.getElementById('page-en')?.value??p.en}}
function detailPage(){const b=activeBook;if(!b){view='library';return libraryPage()}return `${heading('우리 가족의 이야기','종이로 읽고, 익숙한 목소리로 함께 들어요.',btn('책장으로','library','outline','back'))}${b.justCreated?'<div class="success-note">'+icon('check')+'새 동화책이 완성됐어요! 종이책으로 첫 모험을 시작해 볼까요?</div>':''}<div class="detail-layout"><div class="detail-cover">${cover(b)}</div><section class="detail-info"><span class="role-tag">${esc(b.series)} · ${b.episode||1}편</span><h2>${esc(b.title)}</h2><p>${esc(b.titleEn)}</p><div class="metadata"><span><b>${b.pages.length}쪽</b>이야기 길이</span><span><b>${languageLabel(b.language)}</b>읽는 언어</span><span><b>${b.reads||0}번</b>함께 읽었어요</span></div><p>${esc(b.summary||b.pages[0]?.ko)}</p><div class="detail-actions">${!childMode?btn('인쇄 · PDF로 저장','print-options','primary','print',`data-id="${esc(b.id)}"`):''}${btn('책 읽고 듣기','read-book','green','play',`data-id="${esc(b.id)}"`)}${!childMode?btn('다음 편 만들기','continue-book','outline','spark',`data-id="${esc(b.id)}"`):''}</div>${!childMode?`<div class="detail-secondary"><button data-action="favorite" data-id="${esc(b.id)}">${icon('heart')}${b.favorite?'즐겨찾기 해제':'즐겨찾기'}</button><button data-action="paper-read" data-id="${esc(b.id)}">${icon('check')}오늘 종이로 읽음</button><button data-action="branch-book" data-id="${esc(b.id)}">${icon('plus')}새 시리즈</button></div><div class="book-details-note">등장인물: ${(b.characterIds||[]).map(id=>esc(char(id)?.name)).join(', ')}<br>${b.printedAt?'마지막 인쇄 창 열기: '+new Date(b.printedAt).toLocaleDateString('ko-KR'):'아직 인쇄 기록이 없어요.'}${b.paperReadAt?'<br>종이로 읽은 날: '+new Date(b.paperReadAt).toLocaleDateString('ko-KR'):''}</div>`:''}</section></div>`}
function settingsPage(){const s=state.settings;return `${heading('부모 설정','우리 가족의 속도와, 이야기를 읽는 방식을 정해요.')}<form id="settings-form" class="settings"><div class="settings-layout"><div class="settings-stack"><section class="panel"><h3>우리 집 이야기 기본값</h3><div class="form-grid">${selectField('defaultLanguage','기본 언어',[['dual','한글판 · 영어판 두 권'],['bilingual','한 쪽에 두 언어'],['ko','한글만'],['en','영어만']],s.defaultLanguage)}${selectField('defaultPages','기본 쪽수',[[8,'8쪽'],[12,'12쪽'],[16,'16쪽'],[24,'24쪽']],s.defaultPages)}${selectField('defaultLayout','인쇄 레이아웃',[['booklet','소책자 · A5 반 접기'],['single','한 면에 한 쪽'],['two','두 쪽 모아 찍기']],s.defaultLayout)}</div><p class="small-label" style="margin-top:15px">화풍과 이미지 엔진은 아래 World 설정에서 함께 관리해요.</p></section><section class="panel"><h3>아이 모드 · 화면의 속도</h3><p class="section-sub">아이 모드에는 확정된 책과 읽기·듣기만 보여요.</p><div class="form-grid">${selectField('dailyLimit','하루에 앱으로 읽을 책',[[1,'1권'],[2,'2권'],[3,'3권'],[5,'5권'],[0,'제한 없음']],s.dailyLimit)}${selectField('rate','기본 읽기 속도',[[0.65,'천천히'],[0.85,'보통'],[1.05,'조금 빠르게']],s.rate)}</div><div class="notice" style="margin-top:17px">오늘 앱으로 ${state.daily[localDay()]||0}권을 열었어요. 제한에 도달하면 종이책을 권해요. 읽어주기 목소리는 기기에 설치된 음성에 따라 달라집니다.</div></section></div><div class="settings-stack"><section class="panel"><h3>부모 잠금</h3><p class="section-sub">새로고침하면 만들기·설정이 다시 잠깁니다.</p>${btn(state.settings.pinHash?'부모 PIN 바꾸기':'부모 PIN 설정','change-pin','outline','lock')}<p class="small-label" style="margin-top:17px">PIN은 이 브라우저의 화면 잠금입니다. 기기와 브라우저에 접근할 수 있는 사용자를 서버에서 인증하는 기능은 아닙니다.</p></section><section class="panel"><h3>이야기 보관과 백업</h3><p class="section-sub">책과 캐릭터는 이 브라우저에 보관됩니다. 가끔 백업해 우리 가족의 이야기를 남겨 주세요.</p>${btn('전체 라이브러리 ZIP 백업','export-library','green','download')}<div style="margin-top:13px">${btn('library.json에서 복원','import-library','outline','upload')}</div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="small-label" style="margin-top:17px">ZIP 안의 library.json을 꺼내 복원할 수 있어요. PDF는 각 책에서 인쇄 → PDF로 저장을 사용하세요.</p></section><section class="panel"><h3>현재 공방의 기능</h3><p class="small-label">로컬 샘플 이야기 · 고정 캐릭터 SVG · 한영 음성 합성 · A4 인쇄 · 시리즈 · 기기 저장<br><br>이미지 생성은 아래 World 엔진과 API 키로 연결합니다. 글은 로컬 샘플이며 사진 캐릭터 변환은 아직 지원하지 않습니다.</p></section></div></div><div class="settings-save"><button type="submit" class="btn btn-primary">${icon('check')}설정 저장</button></div></form>${renderImageSettings(state)}`}
function openStudio(){studio={name:'',nameEn:'',role:'주인공',kind:'child',age:4,color:'#efc954',hairColor:'#3c3027',skinColor:'#f1cfad',description:'짧은 검은 머리, 노란 티셔츠',traits:'호기심 많음, 씩씩함, 다정함',variant:0};showStudioForm()}
function showStudioForm(){showModal(`${modalHeader('우리 집 이야기 친구 만들기')}<p class="modal-intro">설정으로 만든 고정 캐릭터가 모든 책에 함께 등장해요. 사진 변환은 아직 지원하지 않아요.</p><form id="character-form"><div class="form-grid"><div class="field"><label for="c-name">이름 · 한글</label><input id="c-name" required maxlength="30" placeholder="예: 유하" value="${esc(studio.name)}"></div><div class="field"><label for="c-nameEn">이름 · 영어</label><input id="c-nameEn" required maxlength="40" placeholder="예: Yuha" value="${esc(studio.nameEn)}"></div>${selectField('c-role','역할',[['주인공','주인공'],['가족','가족'],['친구','친구'],['동물','동물'],['상상 친구','상상 친구']],studio.role)}${selectField('c-kind','캐릭터 모습',[['child','아이'],['adult','어른'],['dinosaur','공룡'],['rabbit','토끼']],studio.kind)}<div class="field"><label for="c-age">나이</label><input id="c-age" type="number" min="1" max="99" value="${studio.age}" required></div><div class="field"><label for="c-color">옷 · 몸 색상</label><input id="c-color" type="color" value="${studio.color}" style="height:45px"></div><div class="field"><label for="c-hair">머리 색상</label><input id="c-hair" type="color" value="${studio.hairColor}" style="height:45px"></div><div class="field"><label for="c-skin">피부 색상</label><input id="c-skin" type="color" value="${studio.skinColor}" style="height:45px"></div><div class="field field-wide"><label for="c-description">외모 · 늘 입는 옷 · 고정 특징</label><textarea id="c-description" maxlength="200">${esc(studio.description)}</textarea><small>샘플 캐릭터에서 반영되는 모습은 종류와 색상입니다. 세부 외모는 시트 메모로 저장돼요.</small></div><div class="field field-wide"><label for="c-traits">성격 · 좋아하는 것</label><input id="c-traits" maxlength="120" value="${esc(studio.traits)}"></div></div><div class="modal-actions"><button type="submit" class="btn btn-green">4가지 모습 살펴보기${icon('arrow')}</button></div></form>`)}
function showCandidates(){showModal(`${modalHeader('우리 친구의 모습을 골라요')}<p class="modal-intro">이 모습과 색상을 캐릭터 시트로 고정해요. 미소와 몸짓을 비교해 보세요.</p><div class="candidates">${[0,1,2,3].map(i=>`<button class="candidate ${studio.variant===i?'selected':''}" data-action="candidate" data-variant="${i}">${characterSVG(studio,i)}<span>모습 ${i+1}</span></button>`).join('')}</div><div class="modal-actions">${btn('설정 수정','studio-back','outline','back')}${btn('시험 장면 확인','studio-test','green','arrow')}</div>`,'wide')}
function showStudioTest(){showModal(`${modalHeader('세 장면에서 같은 친구인가요?')}<p class="modal-intro">${esc(studio.name)}의 얼굴과 옷 색상이 같은지 살펴봐요. 확정하면 이야기 재료에 저장됩니다.</p><div class="test-scenes">${['dinosaur','moon','rain'].map((theme,i)=>`<div>${sceneSVG({theme,beat:'explore',index:i},studio,studio.variant)}<p>${['숲속에서','달빛 아래에서','비 오는 날'][i]}</p></div>`).join('')}</div><div class="modal-actions">${btn('다시 고르기','studio-candidates','outline','back')}${btn('이 모습으로 확정','save-character','primary','check')}</div>`,'wide')}
function showCharacter(c){const world=getActiveWorld(state);const sheet=getCharacterSheet(state,c.id,world)||c.characterSheets?.at(-1);const url=sheet?.imageAssetId?getImageURL(sheet.imageAssetId):null;if(sheet?.imageAssetId){showModal(`${modalHeader(esc(c.name)+'의 확정 캐릭터 시트')}${url?`<img class="ig-sheet-preview" src="${esc(url)}" alt="${esc(c.name)}의 확정 캐릭터 시트">`:'<div class="image-missing">저장된 시트 그림을 찾을 수 없어요. 백업에서 복원해 주세요.</div>'}<p class="modal-intro">World v${sheet.worldRevision} · ${esc(sheet.imageEngine)} · ${esc(getStylePreset(sheet.stylePresetId).name)}<br>요청 시드 ${sheet.requestedSeed??sheet.meta?.requestedSeed??'—'} · 결과 시드 ${sheet.seed??'미지원'}${sheet.worldRevision!==world.revision?'<br><strong>현재 World의 시트 다시 생성 필요</strong>':''}</p><div class="modal-actions">${btn('닫기','close-modal','green')}</div>`,'wide');return}showModal(`${modalHeader(esc(c.name)+'의 캐릭터 시트')}<div class="form-grid"><div class="character-picture" style="height:240px">${characterSVG(c,c.variant||0)}</div><div><span class="role-tag">${esc(c.role)} · v${c.version||1}</span><h3 style="font-family:var(--serif)">${esc(c.name)} / ${esc(c.nameEn)}</h3><p class="small-label">${esc(c.description)}</p><p class="small-label">${esc(Array.isArray(c.traits)?c.traits.join(', '):c.traits)}</p><p class="small-label">고정 색상: ${esc(c.color)}<br>모든 책에서 이 시트를 사용합니다.</p></div></div><div class="test-scenes">${[0,1,2].map(i=>`<div>${characterSVG(c,i)}<p>${['기쁨','호기심','놀람'][i]}</p></div>`).join('')}</div><div class="modal-actions">${btn('새 버전 만들기','version-character','outline','plus',`data-id="${esc(c.id)}"`)}${btn('닫기','close-modal','green')}</div>`,'wide')}
function showBackgroundForm(){showModal(`${modalHeader('이야기가 머무는 장소')}<form id="background-form"><div class="form-grid"><div class="field"><label for="b-name">장소 이름</label><input id="b-name" required maxlength="50" placeholder="예: 유하네 놀이터"></div>${selectField('b-type','장소 종류',[['home','집'],['school','유치원'],['forest','숲 · 놀이터'],['sea','바다'],['space','우주 · 상상 세계']], 'forest')}<div class="field field-wide"><label for="b-description">특징과 분위기</label><textarea id="b-description" maxlength="250" placeholder="큰 나무 아래 노란 미끄럼틀이 있는 아늑한 놀이터" required></textarea><small>장소 설정을 이야기 맥락으로 저장합니다. 사진 기반 배경 그림은 아직 지원하지 않아요.</small></div></div><div class="modal-actions"><button type="submit" class="btn btn-green">${icon('check')}배경에 저장</button></div></form>`)}
function showPrintOptions(b){showModal(`${modalHeader('종이책으로 만나기')}<p class="modal-intro">${esc(b.title)} · A4 인쇄 창에서 프린터 또는 ‘PDF로 저장’을 선택해 주세요.</p><form id="print-form" data-id="${esc(b.id)}"><div class="form-grid">${selectField('p-layout','레이아웃',[['booklet','소책자 · 양면으로 반 접기'],['single','한 면에 한 쪽'],['two','두 쪽 모아 찍기']],state.settings.defaultLayout)}${selectField('p-language','출력 언어',[['ko','한글판'],['en','영어판'],['bilingual','한 면에 영어 + 한글']],b.language==='en'?'en':b.language==='bilingual'?'bilingual':'ko')}<div class="field"><label for="p-pages">출력 쪽</label><input id="p-pages" value="all" placeholder="all / cover / 3-8 / 2,4,6"><small>all: 전체 · cover: 표지만 · 범위 또는 쉼표 구분</small></div>${selectField('p-color','색상',[['color','컬러'],['grayscale','흑백']], 'color')}${selectField('p-fontSize','글자 크기',[['large','크게'],['normal','보통']], 'large')}${selectField('p-margin','여백',[['standard','표준 · 10mm'],['binding','제본용 · 안쪽 여백 넓게']], 'standard')}</div><div class="notice" style="margin-top:20px">소책자는 표지·뒤표지와 빈 쪽을 포함해 4의 배수로 맞추고 쪽 순서를 재배치합니다. A4 가로 · 양면 · 짧은 쪽 뒤집기로 먼저 한 장 시험 인쇄해 주세요.<br>권장 종이: 120–160g · 반 접어 스테이플러 또는 링으로 묶어요.</div><div class="modal-actions"><button type="submit" class="btn btn-primary">${icon('print')}인쇄 창 열기</button></div></form>`)}
function startReading(b){if(!b||b.approved===false)return;const count=state.daily[localDay()]||0;if(childMode&&state.settings.dailyLimit>0&&count>=state.settings.dailyLimit){showModal(`${icon('leaf')}<h3 style="font-family:var(--serif);font-size:25px">이제 종이책으로 읽자</h3><p class="modal-intro">오늘은 화면으로 충분히 만났어요.<br>책장 밖에서도 이야기는 계속될 거예요.</p>${btn('책장으로','close-modal','green')}`,'pin-modal');return}state.daily[localDay()]=count+1;b.reads=(b.reads||0)+1;b.lastReadAt=new Date().toISOString();save();reader={book:b,page:0,rate:Number(state.settings.rate),continuous:false,audioOnly:false,speaking:false,lastLanguage:b.language==='en'?'en':'ko'};renderReader()}
function renderReader(){const r=reader;if(!r)return;const b=r.book,p=b.pages[r.page];showModal(`<div class="reader-top"><strong>${esc(b.title)}</strong><small>${r.page+1} / ${b.pages.length}쪽</small><button class="close-btn" data-action="close-modal" aria-label="읽기 닫기">${icon('close')}</button></div><div class="reader-page"><div class="reader-picture">${illustration(b,r.page)}</div><div class="reader-body"><div class="audio-indicator">${icon('headphones')}종이책을 보며 들어요</div>${b.language!=='en'?`<div class="ko">${esc(p.ko)}</div>`:''}${b.language!=='ko'?`<div class="en">${esc(p.en)}</div>`:''}<div class="reader-lang-actions">${b.language!=='en'?btn('한글로 듣기','speak-ko','soft','volume'):''}${b.language!=='ko'?btn('Listen in English','speak-en','outline','volume'):''}${btn('멈춤','stop-speech','outline','pause')}</div></div></div><div class="reader-pagination"><button class="btn btn-outline" data-action="reader-prev" ${r.page===0?'disabled':''} aria-label="이전 쪽">${icon('back')}</button><span>${r.page+1} / ${b.pages.length}</span><button class="btn btn-outline" data-action="reader-next" ${r.page===b.pages.length-1?'disabled':''} aria-label="다음 쪽">${icon('chevron')}</button></div><div class="reader-options"><label>속도 <select id="reader-rate"><option value="0.65" ${r.rate===0.65?'selected':''}>천천히</option><option value="0.85" ${r.rate===0.85?'selected':''}>보통</option><option value="1.05" ${r.rate===1.05?'selected':''}>조금 빠르게</option></select></label><label><input type="checkbox" id="reader-continuous" ${r.continuous?'checked':''}>이어 듣기</label><button data-action="audio-only">${r.audioOnly?'그림과 글 보기':'듣기 전용'}</button></div><div class="reader-status" id="reader-status">재생 버튼을 누르면 이 쪽을 읽어줘요.</div>`,'reader '+(r.audioOnly?'audio-only':''))}
let speechToken=0;function stopSpeech(){speechToken++;if('speechSynthesis'in window)speechSynthesis.cancel();if(reader)reader.speaking=false;const s=document.querySelector('#reader-status');if(s)s.textContent='재생 버튼을 누르면 이 쪽을 읽어줘요.'}
function speak(language){if(!reader)return;if(!('speechSynthesis'in window)){toast('이 브라우저는 읽어주기를 지원하지 않아요.');return}stopSpeech();const token=speechToken;const r=reader;r.lastLanguage=language;r.speaking=true;const text=r.book.pages[r.page][language];const u=new SpeechSynthesisUtterance(text);u.lang=language==='ko'?'ko-KR':'en-US';u.rate=r.rate;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang.toLowerCase().startsWith(language==='ko'?'ko':'en'))||null;const status=document.querySelector('#reader-status');if(status)status.textContent=language==='ko'?'한글로 읽고 있어요…':'Listening in English…';u.onend=()=>{if(token!==speechToken||!reader)return;reader.speaking=false;if(reader.continuous&&reader.page<reader.book.pages.length-1){reader.page++;renderReader();speak(language)}else{const s=document.querySelector('#reader-status');if(s)s.textContent=reader.page===reader.book.pages.length-1?'이야기가 끝났어요. 잘 자, 작은 모험가.':'한 번 더 듣거나 다음 쪽으로 넘겨보세요.'}};u.onerror=e=>{if(token!==speechToken||e.error==='interrupted'||e.error==='canceled')return;reader.speaking=false;const s=document.querySelector('#reader-status');if(s)s.textContent='기기 음성을 사용할 수 없어요. 음성 설정을 확인해 주세요.'};speechSynthesis.speak(u)}
function discardDraft(next){if(draft&&view==='edit'){syncDraft();showModal(`${modalHeader('아직 확정하지 않은 이야기예요')}<p class="modal-intro">확정 전 초안은 책장에 저장되지 않습니다. 책장을 나가면 이번 초안을 잃게 돼요.</p><div class="modal-actions">${btn('계속 다듬기','close-modal','outline')}<button class="btn btn-primary" id="discard-confirm">초안 버리고 이동</button></div>`);document.querySelector('#discard-confirm').onclick=()=>{draft=null;closeModal();next()}}else next()}
root.addEventListener('click',onAction);modalRoot.addEventListener('click',onAction);
async function onAction(e){const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='close-modal'){closeModal();return}
 if(a==='toggle-mode'){if(childMode)protectedAction(()=>{view='library';tab='all';render()});else discardDraft(()=>{childMode=true;parentUnlocked=false;view='library';tab='all';render();toast('아이 모드에서는 읽기와 듣기만 열려요.')});return}
 if(a==='nav'){const go=()=>discardDraft(()=>{view=el.dataset.view;if(view==='create'&&!wizard)startStory();else render();window.scrollTo(0,0)});if(el.dataset.view==='library')go();else protectedAction(go);return}
 if(a==='library'){discardDraft(()=>{view='library';activeBook=null;render()});return}
 if(a==='child-favorites'){view='library';tab='favorites';render();return}
 if(a==='tab'){tab=el.dataset.tab;render();return}
 if(a==='open-book'){activeBook=bookById(id);view='detail';render();window.scrollTo(0,0);return}
 if(a==='favorite'){protectedAction(()=>{const b=bookById(id);b.favorite=!b.favorite;save();render();toast(b.favorite?'좋아하는 책에 담았어요.':'즐겨찾기에서 꺼냈어요.')});return}
 if(a==='new-story'){protectedAction(()=>startStory());return}
 if(a==='continue-book'||a==='branch-book'){protectedAction(()=>{startStory(bookById(id));if(a==='branch-book'){wizard.previousBookId=null;wizard.series='';render()}});return}
 if(a==='select-character'){const ids=wizard.characterIds;if(ids.includes(id))wizard.characterIds=ids.filter(v=>v!==id);else if(ids.length<5)ids.push(id);else toast('주인공과 조연을 합해 최대 5명이에요.');render();return}
 if(a==='select-background'){const ids=wizard.backgroundIds;if(ids.includes(id))wizard.backgroundIds=ids.filter(v=>v!==id);else if(ids.length<3)ids.push(id);else toast('배경은 최대 3곳을 고를 수 있어요.');render();return}
 if(a==='wizard-back'){syncWizard();wizard.step--;render();return}
 if(a==='wizard-next'){syncWizard();if(wizard.step===1&&!wizard.characterIds.length){toast('주인공을 한 명 골라 주세요.');return}if(wizard.step===2){const check=safeTopic(wizard.topic);if(!check.ok){toast(check.message||'이야기 주제를 입력해 주세요.');return}wizard.outline=makeOutline(wizard,state.characters);if(wizard.previousBookId&&wizard.outline.length){wizard.outline[0].ko='지난 모험을 마친 '+char(wizard.characterIds[0]).name+'에게 새 아침이 왔어요. 오늘도 함께 출발해요.';wizard.outline[0].en='Here we go again, little friend.'}}wizard.step++;render();window.scrollTo(0,0);return}
 if(a==='topic-chip'){document.getElementById('topic').value=el.dataset.topic;wizard.topic=el.dataset.topic;return}
 if(a==='child-pick'){syncWizard();showModal(`${modalHeader('어떤 모험이 좋아?')}<p class="modal-intro">그림 하나를 손가락으로 골라 주세요.</p><div class="theme-cards">${[['🦕','공룡','공룡 친구와 소풍'],['🌙','달','달에 놀러 간 날'],['🐳','바다','바닷속 보물 찾기']].map(([emoji,label,topic])=>`<button class="theme-card" data-action="pick-topic" data-topic="${topic}"><span>${emoji}</span><strong>${label}</strong></button>`).join('')}</div>`);return}
 if(a==='pick-topic'){wizard.topic=el.dataset.topic;closeModal();render();return}
 if(a==='generate'){syncWizard();if(wizard.outline.some(p=>!p.ko.trim())){toast('모든 쪽의 줄거리를 채워 주세요.');return}draft=generateBook(wizard,wizard.outline,state.characters,state.books);draft.approved=false;draft.backgroundIds=[...wizard.backgroundIds];draft.style=state.settings.style;draft.worldId=getActiveWorld(state).id;editPage=0;view='edit';render();window.scrollTo(0,0);return}
 if(a==='edit-page'){syncDraft();editPage=Number(el.dataset.page);render();return}
 if(a==='regenerate-art'){syncDraft();if(draft.pages[editPage].imageAssetId){toast('생성한 그림은 ‘이 쪽 그림 생성’으로 다시 만들 수 있어요.');return}draft.pages[editPage].artVariant=(draft.pages[editPage].artVariant||0)+1;render();toast('이 쪽의 그림 구도를 바꿨어요.');return}
 if(a==='regenerate-text'){syncDraft();const p=regenerateText(draft,editPage);draft.pages[editPage]={...draft.pages[editPage],...p};render();toast('이 쪽의 샘플 문장을 다시 썼어요.');return}
 if(a==='approve-book'){syncDraft();if(!draft.title.trim()||draft.pages.some(p=>!p.ko.trim()||!p.en.trim())){toast('제목과 각 쪽의 한글·영어 글을 확인해 주세요.');return}draft.approved=true;draft.justCreated=true;state.books.unshift(draft);if(!save()){state.books.shift();return}activeBook=draft;draft=null;wizard=null;view='detail';render();window.scrollTo(0,0);toast('우리 가족의 새 이야기를 책장에 담았어요.');return}
 if(a==='new-character'){protectedAction(openStudio);return}
 if(a==='candidate'){studio.variant=Number(el.dataset.variant);showCandidates();return}
 if(a==='studio-back'){showStudioForm();return}
 if(a==='studio-candidates'){showCandidates();return}
 if(a==='studio-test'){showStudioTest();return}
 if(a==='save-character'){const c={...studio,id:'char-'+crypto.randomUUID(),traits:studio.traits.split(',').map(t=>t.trim()),version:(studio.version||0)+1,characterSheets:[],wardrobe:[],createdAt:new Date().toISOString()};state.characters.push(c);markCharacterSheetConfirmed(state,c.id,{imageUrl:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(characterSVG(c,c.variant||0)),seed:null,meta:{source:'local-svg',requestedSeed:crypto.getRandomValues(new Uint32Array(1))[0]&0x7fffffff}});if(!save()){state.characters.pop();return}closeModal();view='materials';render();toast(c.name+'의 모습을 이야기 재료에 저장했어요.');return}
 if(a==='character-sheet'){protectedAction(()=>showCharacter(char(id)));return}
 if(a==='version-character'){studio={...char(id),traits:Array.isArray(char(id).traits)?char(id).traits.join(', '):char(id).traits,name:char(id).name+' (새 버전)'};showStudioForm();return}
 if(a==='new-background'){protectedAction(showBackgroundForm);return}
 if(a==='print-options'){protectedAction(()=>showPrintOptions(bookById(id)));return}
 if(a==='read-book'){startReading(bookById(id));return}
 if(a==='paper-read'){protectedAction(()=>{const b=bookById(id);b.paperReads=(b.paperReads||0)+1;b.paperReadAt=new Date().toISOString();save();render();toast('오늘 종이책으로 읽은 날을 기록했어요.')});return}
 if(a==='speak-ko'||a==='speak-en'){speak(a==='speak-ko'?'ko':'en');return}
 if(a==='stop-speech'){stopSpeech();return}
 if(a==='reader-next'||a==='reader-prev'){stopSpeech();reader.page+=a==='reader-next'?1:-1;reader.page=Math.max(0,Math.min(reader.book.pages.length-1,reader.page));renderReader();return}
 if(a==='audio-only'){reader.audioOnly=!reader.audioOnly;modalRoot.querySelector('.reader')?.classList.toggle('audio-only',reader.audioOnly);el.textContent=reader.audioOnly?'그림과 글 보기':'듣기 전용';return}
 if(a==='change-pin'){showModal(`${modalHeader('부모 PIN 바꾸기')}<p class="modal-intro">새로 사용할 숫자 4자리를 두 번 입력해 주세요.</p><form id="change-pin-form"><div class="form-grid"><div class="field"><label for="new-pin">새 PIN</label><input id="new-pin" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required autocomplete="off"></div><div class="field"><label for="confirm-pin">새 PIN 확인</label><input id="confirm-pin" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required autocomplete="off"></div></div><p class="text-error" id="change-pin-error"></p><div class="modal-actions"><button class="btn btn-green" type="submit">PIN 저장</button></div></form>`);return}
 if(a==='export-library'){protectedAction(async()=>{try{const r=await exportLibrary(state);toast(r.bookCount+'권과 이야기 재료를 ZIP으로 백업했어요.')}catch(err){toast(err.message)}});return}
 if(a==='import-library'){protectedAction(()=>document.querySelector('#import-file').click());return}
}
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;
 if(f.id==='pin-form'){const pin=document.querySelector('#pin').value;const error=document.querySelector('#pin-error');if(!/^\d{4}$/.test(pin)){error.textContent='숫자 4자리를 입력해 주세요.';return}if(!state.settings.pinHash&&pin!==document.querySelector('#pin-confirm').value){error.textContent='두 PIN이 달라요. 다시 확인해 주세요.';return}const h=await hashPin(pin);if(state.settings.pinHash&&state.settings.pinHash!==h){error.textContent='PIN이 맞지 않아요.';document.querySelector('#pin').value='';return}if(!state.settings.pinHash){state.settings.pinHash=h;if(!save())return}const next=pinCallback;closeModal();parentUnlocked=true;childMode=false;if(next)next();else render();return}
 if(f.id==='settings-form'){for(const k of ['defaultLanguage','defaultPages','defaultLayout','dailyLimit','rate'])state.settings[k]=document.getElementById(k).value;for(const k of ['defaultPages','dailyLimit','rate'])state.settings[k]=Number(state.settings[k]);if(save())toast('우리 가족의 기본 설정을 저장했어요.');return}
 if(f.id==='change-pin-form'){const p=document.getElementById('new-pin').value;if(p!==document.getElementById('confirm-pin').value){document.getElementById('change-pin-error').textContent='두 PIN이 달라요.';return}state.settings.pinHash=await hashPin(p);if(save()){closeModal();toast('부모 PIN을 바꿨어요.')}return}
 if(f.id==='character-form'){for(const [k,id] of [['name','c-name'],['nameEn','c-nameEn'],['role','c-role'],['kind','c-kind'],['age','c-age'],['color','c-color'],['hairColor','c-hair'],['skinColor','c-skin'],['description','c-description'],['traits','c-traits']])studio[k]=document.getElementById(id).value.trim();studio.age=Number(studio.age);if(!studio.name||!studio.nameEn){toast('한글·영어 이름을 입력해 주세요.');return}showCandidates();return}
 if(f.id==='background-form'){state.backgrounds.push({id:'bg-'+crypto.randomUUID(),name:document.getElementById('b-name').value.trim(),type:document.getElementById('b-type').value,description:document.getElementById('b-description').value.trim()});if(save()){closeModal();render();toast('다음 이야기에도 꺼내 쓸 수 있는 장소가 생겼어요.')}return}
 if(f.id==='print-form'){const b=bookById(f.dataset.id);const s={};for(const k of ['layout','language','pages','color','fontSize','margin'])s[k]=document.getElementById('p-'+k).value;try{if(printBook(b,s,state.characters)){b.printedAt=new Date().toISOString();save();closeModal();render();toast('인쇄 창에서 프린터 또는 PDF 저장을 선택해 주세요.')}else toast('팝업을 허용한 뒤 인쇄 창을 다시 열어 주세요.')}catch(err){toast(err.message)}return}
});
document.addEventListener('input',e=>{if(e.target.id==='search-books'){query=e.target.value;const books=filteredBooks();document.querySelector('#books-grid').innerHTML=tab==='series'?[...Map.groupBy(books,b=>b.series)].map(([s,list])=>`<section class="series-group"><h3>${esc(s)}</h3><div class="books-grid">${list.map(bookCard).join('')}</div></section>`).join(''):books.map(bookCard).join('')||'<div class="empty">찾는 이야기가 아직 없어요. 다른 검색어로 찾아보세요.</div>';document.querySelector('.shelf-title .count').textContent=books.length+'권의 이야기'}});
document.addEventListener('change',async e=>{if(e.target.id==='sort'){sort=e.target.value;render()}if(e.target.id==='reader-rate'){reader.rate=Number(e.target.value)}if(e.target.id==='reader-continuous'){reader.continuous=e.target.checked}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{const imported=validateImport(await file.text());showModal(`${modalHeader('백업으로 라이브러리 복원')}<p class="modal-intro">백업에 있는 ${imported.books.length}권의 책과 ${imported.characters.length}명의 캐릭터로 현재 라이브러리를 교체합니다. 현재 데이터는 먼저 ZIP으로 백업하는 것이 좋아요. 부모 PIN은 현재 값을 유지합니다.</p><div class="modal-actions">${btn('취소','close-modal','outline')}<button class="btn btn-primary" id="restore-confirm">이 백업으로 복원</button></div>`);document.querySelector('#restore-confirm').onclick=async()=>{try{await restoreLibraryImages(imported);}catch(error){toast(error.message);return}const previousState=state;state={...imported,settings:{...defaults,...imported.settings,pinHash:state.settings.pinHash},daily:imported.daily||{}};migrateWorldState(state);if(!save()){state=previousState;return}closeModal();view='library';tab='all';query='';wizard=null;draft=null;render();toast('이야기와 재료를 복원했어요.')};}catch(err){toast(err.message)}}});
document.addEventListener('keydown',e=>{if(!modalRoot.firstChild)return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focus=[...modalRoot.querySelectorAll('button:not(:disabled),input:not([hidden]),textarea,select')].filter(x=>x.offsetParent!==null);const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(reader&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){if(e.key==='ArrowRight'&&reader.page<reader.book.pages.length-1){stopSpeech();reader.page++;renderReader()}if(e.key==='ArrowLeft'&&reader.page>0){stopSpeech();reader.page--;renderReader()}}});
configureImageUI({getState:()=>state,save,toast,modalHeader,showModal,closeModal,render,protectedAction,syncDraft,getDraft:()=>draft,getEditPage:()=>editPage,isParent:()=>parentUnlocked&&!childMode});
window.addEventListener('beforeunload',e=>{stopSpeech();if(draft){e.preventDefault();e.returnValue=''}});
render();hydrateImageAssets(state).then(result=>{render();if(result.missing.length)toast('저장된 그림 '+result.missing.length+'장을 찾을 수 없어요. 이미지가 포함된 백업에서 복원해 주세요.')}).catch(error=>toast(error.message));
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
